----------------------------------------------------------------------------------------
-- 6. OPUS — [M1 | stitch_incremental] SAT_COMMON_ADDRESS   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- sat_multi_source; PK LOCATION_HKEY; 2 RECORD_SOURCE group(s): stitch_common_address (5
-- tables) [11 col(s)], stitch_kyc_common_address (6 tables) [11 col(s)]. Stitch groups:
-- expected values are the stitch view recomputed from RAW (same coalesce priority and
-- tie-break), and RECORD_SOURCE (contributing tables) is compared too.
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES)(, (OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES))*$')
     group by LOCATION_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select LOCATION_HKEY as hkey,
           to_varchar(ADDRESSLINE1) as ADDRESSLINE1,
           to_varchar(ADDRESSLINE2) as ADDRESSLINE2,
           to_varchar(ADDRESSLINE3) as ADDRESSLINE3,
           to_varchar(BUILDINGNAME) as BUILDINGNAME,
           to_varchar(CITY) as CITY,
           to_varchar(COUNTRYCODE) as COUNTRYCODE,
           to_varchar(COUNTRYNAME) as COUNTRYNAME,
           to_varchar(DOORNUMBER) as DOORNUMBER,
           to_varchar(POSTALCODE) as POSTALCODE,
           to_varchar(STATENAME) as STATENAME,
           to_varchar(STREETNAME) as STREETNAME,
           RECORD_SOURCE as RECORD_SOURCE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES)(, (OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES))*$')
       and LOCATION_HKEY in (select hkey from s1)
    qualify rank() over (partition by LOCATION_HKEY order by LOAD_DATETIME desc) = 1
),
g1_t0 as (  -- stitch source OPUS_AZBJ_ADDRESS_EXTN
    select distinct (nullif(trim("ADD_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE6"::varchar), '')))), '') as addressline2,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE7"::varchar), '')))), '') as addressline3,
           nullif(trim(to_varchar((nullif(trim("BUILDING_NAME"::varchar), '')))), '') as buildingname,
           nullif(trim(to_varchar((nullif(trim("RESIDENCE_COUNTRY"::varchar), '')))), '') as countryname,
           nullif(trim(to_varchar((nullif(trim("DOOR_NO"::varchar), '')))), '') as doornumber,
           nullif(trim(to_varchar((nullif(trim("PLOT_STREET_NO"::varchar), '')))), '') as streetname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_ADDRESS_EXTN
     where (nullif(trim("ADD_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("ADD_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t1 as (  -- stitch source OPUS_BJAZ_CLM_SUPP_EXTN
    select distinct (nullif(trim("BILLING_LOC"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO_ADD_LINE1"::varchar), '')))), '') as addressline1,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO_ADD_LINE2"::varchar), '')))), '') as addressline2,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO_ADD_LINE3"::varchar), '')))), '') as addressline3,
           nullif(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), '')))), '') as countrycode,
           nullif(trim(to_varchar((nullif(trim("COUNTRY"::varchar), '')))), '') as countryname,
           nullif(trim(to_varchar((nullif(trim("BILLING_STATE"::varchar), '')))), '') as statename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where (nullif(trim("BILLING_LOC"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("BILLING_LOC"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t3 as (  -- stitch source OPUS_BJAZ_PINCODE
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("CITY"::varchar), '')))), '') as city,
           nullif(trim(to_varchar((nullif(trim("STATUS"::varchar), '')))), '') as postalcode,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as statename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t4 as (  -- stitch source OPUS_BJAZ_PINCODE_MASTER
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("CITY"::varchar), '')))), '') as city,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as statename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t5 as (  -- stitch source OPUS_CP_ADDRESSES
    select distinct (nullif(trim("ADD_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE1"::varchar), '')))), '') as addressline1,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE2"::varchar), '')))), '') as addressline2,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE3"::varchar), '')))), '') as addressline3,
           nullif(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), '')))), '') as countrycode,
           nullif(trim(to_varchar((nullif(trim("POSTCODE"::varchar), '')))), '') as postalcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_ADDRESSES
     where (nullif(trim("ADD_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("ADD_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t1
    union
    select parent_bk from g1_t3
    union
    select parent_bk from g1_t4
    union
    select parent_bk from g1_t5
),
st1 as (  -- stitch_common_address recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           coalesce(g1_t1.addressline1, g1_t5.addressline1) as addressline1,
           coalesce(g1_t0.addressline2, g1_t1.addressline2, g1_t5.addressline2) as addressline2,
           coalesce(g1_t0.addressline3, g1_t1.addressline3, g1_t5.addressline3) as addressline3,
           g1_t0.buildingname as buildingname,
           coalesce(g1_t3.city, g1_t4.city) as city,
           coalesce(g1_t1.countrycode, g1_t5.countrycode) as countrycode,
           coalesce(g1_t0.countryname, g1_t1.countryname) as countryname,
           g1_t0.doornumber as doornumber,
           coalesce(g1_t3.postalcode, g1_t5.postalcode) as postalcode,
           coalesce(g1_t1.statename, g1_t3.statename, g1_t4.statename) as statename,
           g1_t0.streetname as streetname,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_AZBJ_ADDRESS_EXTN' end,
               case when g1_t1.parent_bk is not null then 'OPUS_BJAZ_CLM_SUPP_EXTN' end,
               case when g1_t3.parent_bk is not null then 'OPUS_BJAZ_PINCODE' end,
               case when g1_t4.parent_bk is not null then 'OPUS_BJAZ_PINCODE_MASTER' end,
               case when g1_t5.parent_bk is not null then 'OPUS_CP_ADDRESSES' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t1.inc_job_updated_at, g1_t3.inc_job_updated_at, g1_t4.inc_job_updated_at, g1_t5.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t1 on g1_t1.parent_bk = ak.parent_bk
      left join g1_t3 on g1_t3.parent_bk = ak.parent_bk
      left join g1_t4 on g1_t4.parent_bk = ak.parent_bk
      left join g1_t5 on g1_t5.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.addressline2 nulls last, g1_t0.addressline3 nulls last, g1_t0.buildingname nulls last, g1_t0.countryname nulls last, g1_t0.doornumber nulls last, g1_t0.streetname nulls last, g1_t1.addressline1 nulls last, g1_t1.addressline2 nulls last, g1_t1.addressline3 nulls last, g1_t1.countrycode nulls last, g1_t1.countryname nulls last, g1_t1.statename nulls last, g1_t3.city nulls last, g1_t3.postalcode nulls last, g1_t3.statename nulls last, g1_t4.city nulls last, g1_t4.statename nulls last, g1_t5.addressline1 nulls last, g1_t5.addressline2 nulls last, g1_t5.addressline3 nulls last, g1_t5.countrycode nulls last, g1_t5.postalcode nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_common_address
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.addressline1) as ADDRESSLINE1,
               to_varchar(st.addressline2) as ADDRESSLINE2,
               to_varchar(st.addressline3) as ADDRESSLINE3,
               to_varchar(st.buildingname) as BUILDINGNAME,
               to_varchar(st.city) as CITY,
               to_varchar(st.countrycode) as COUNTRYCODE,
               to_varchar(st.countryname) as COUNTRYNAME,
               to_varchar(st.doornumber) as DOORNUMBER,
               to_varchar(st.postalcode) as POSTALCODE,
               to_varchar(st.statename) as STATENAME,
               to_varchar(st.streetname) as STREETNAME,
               st.record_source as RECORD_SOURCE
          from st1 st
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'ADDRESSLINE1' as column_name, c.hkey, c.ADDRESSLINE1 as sat_value,
           max(iff(equal_null(c.ADDRESSLINE1, e.ADDRESSLINE1), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ADDRESSLINE1) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ADDRESSLINE1
    union all
    select 'ADDRESSLINE2' as column_name, c.hkey, c.ADDRESSLINE2 as sat_value,
           max(iff(equal_null(c.ADDRESSLINE2, e.ADDRESSLINE2), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ADDRESSLINE2) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ADDRESSLINE2
    union all
    select 'ADDRESSLINE3' as column_name, c.hkey, c.ADDRESSLINE3 as sat_value,
           max(iff(equal_null(c.ADDRESSLINE3, e.ADDRESSLINE3), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ADDRESSLINE3) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ADDRESSLINE3
    union all
    select 'BUILDINGNAME' as column_name, c.hkey, c.BUILDINGNAME as sat_value,
           max(iff(equal_null(c.BUILDINGNAME, e.BUILDINGNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.BUILDINGNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.BUILDINGNAME
    union all
    select 'CITY' as column_name, c.hkey, c.CITY as sat_value,
           max(iff(equal_null(c.CITY, e.CITY), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.CITY) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.CITY
    union all
    select 'COUNTRYCODE' as column_name, c.hkey, c.COUNTRYCODE as sat_value,
           max(iff(equal_null(c.COUNTRYCODE, e.COUNTRYCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.COUNTRYCODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.COUNTRYCODE
    union all
    select 'COUNTRYNAME' as column_name, c.hkey, c.COUNTRYNAME as sat_value,
           max(iff(equal_null(c.COUNTRYNAME, e.COUNTRYNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.COUNTRYNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.COUNTRYNAME
    union all
    select 'DOORNUMBER' as column_name, c.hkey, c.DOORNUMBER as sat_value,
           max(iff(equal_null(c.DOORNUMBER, e.DOORNUMBER), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DOORNUMBER) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DOORNUMBER
    union all
    select 'POSTALCODE' as column_name, c.hkey, c.POSTALCODE as sat_value,
           max(iff(equal_null(c.POSTALCODE, e.POSTALCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.POSTALCODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.POSTALCODE
    union all
    select 'STATENAME' as column_name, c.hkey, c.STATENAME as sat_value,
           max(iff(equal_null(c.STATENAME, e.STATENAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STATENAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.STATENAME
    union all
    select 'STREETNAME' as column_name, c.hkey, c.STREETNAME as sat_value,
           max(iff(equal_null(c.STREETNAME, e.STREETNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STREETNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.STREETNAME
    union all
    select 'RECORD_SOURCE' as column_name, c.hkey, c.RECORD_SOURCE as sat_value,
           max(iff(equal_null(c.RECORD_SOURCE, e.RECORD_SOURCE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.RECORD_SOURCE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.RECORD_SOURCE
),
s2 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where regexp_like(RECORD_SOURCE, '^(OPUS_BJAZ_M_KYC_DRIVING_LICENCE|OPUS_BJAZ_M_KYC_GSTN|OPUS_BJAZ_M_KYC_VOTER|OPUS_BJAZ_T_CKYC_PERSONAL_DTLS|OPUS_BJAZ_T_EKYC|OPUS_BJAZ_T_KYC_OCR)(, (OPUS_BJAZ_M_KYC_DRIVING_LICENCE|OPUS_BJAZ_M_KYC_GSTN|OPUS_BJAZ_M_KYC_VOTER|OPUS_BJAZ_T_CKYC_PERSONAL_DTLS|OPUS_BJAZ_T_EKYC|OPUS_BJAZ_T_KYC_OCR))*$')
     group by LOCATION_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select LOCATION_HKEY as hkey,
           to_varchar(ADDRESSLINE1) as ADDRESSLINE1,
           to_varchar(ADDRESSLINE2) as ADDRESSLINE2,
           to_varchar(ADDRESSLINE3) as ADDRESSLINE3,
           to_varchar(BUILDINGNAME) as BUILDINGNAME,
           to_varchar(CITY) as CITY,
           to_varchar(COUNTRYCODE) as COUNTRYCODE,
           to_varchar(COUNTRYNAME) as COUNTRYNAME,
           to_varchar(DOORNUMBER) as DOORNUMBER,
           to_varchar(POSTALCODE) as POSTALCODE,
           to_varchar(STATENAME) as STATENAME,
           to_varchar(STREETNAME) as STREETNAME,
           RECORD_SOURCE as RECORD_SOURCE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where regexp_like(RECORD_SOURCE, '^(OPUS_BJAZ_M_KYC_DRIVING_LICENCE|OPUS_BJAZ_M_KYC_GSTN|OPUS_BJAZ_M_KYC_VOTER|OPUS_BJAZ_T_CKYC_PERSONAL_DTLS|OPUS_BJAZ_T_EKYC|OPUS_BJAZ_T_KYC_OCR)(, (OPUS_BJAZ_M_KYC_DRIVING_LICENCE|OPUS_BJAZ_M_KYC_GSTN|OPUS_BJAZ_M_KYC_VOTER|OPUS_BJAZ_T_CKYC_PERSONAL_DTLS|OPUS_BJAZ_T_EKYC|OPUS_BJAZ_T_KYC_OCR))*$')
       and LOCATION_HKEY in (select hkey from s2)
    qualify rank() over (partition by LOCATION_HKEY order by LOAD_DATETIME desc) = 1
),
g2_t0 as (  -- stitch source OPUS_BJAZ_M_KYC_DRIVING_LICENCE
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("ADDRESS"::varchar), ''))))), '') as addressline1,
           nullif(trim(to_varchar(upper((nullif(trim("ZIP_CODE"::varchar), ''))))), '') as postalcode,
           nullif(trim(to_varchar(upper((nullif(trim("STATE"::varchar), ''))))), '') as statename,
           nullif(trim(to_varchar(cast(null as varchar))), '') as careofname,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_DRIVING_LICENCE
     where case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
),
g2_t1 as (  -- stitch source OPUS_BJAZ_M_KYC_GSTN
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') as addressline1,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_GSTN
     where case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
),
g2_t2 as (  -- stitch source OPUS_BJAZ_M_KYC_VOTER
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("PART_NAME"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("STATE"::varchar), ''))))), '') as statename,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_VOTER
     where case when nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("PART_NAME"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("PART_NAME"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
