),
g2_t7 as (  -- stitch source OPUS_BJAZ_T_KYC_OCR
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("BUILDING"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("HOUSE_NUMBER"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("PIN_CODE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STREET"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("HOUSE_NUMBER"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUILDING"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STREET"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("LOCATION"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("POST_OFFICE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PIN_CODE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("BUILDING"::varchar), ''))))), '') as buildingname,
           nullif(trim(to_varchar(upper((nullif(trim("COUNTRY_CODE"::varchar), ''))))), '') as countrycode,
           nullif(trim(to_varchar(upper((nullif(trim("HOUSE_NUMBER"::varchar), ''))))), '') as doornumber,
           nullif(trim(to_varchar(upper((nullif(trim("PIN_CODE"::varchar), ''))))), '') as postalcode,
           nullif(trim(to_varchar(upper((nullif(trim("STATE"::varchar), ''))))), '') as statename,
           nullif(trim(to_varchar(upper((nullif(trim("STREET"::varchar), ''))))), '') as streetname,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_OCR
     where case when nullif(upper(trim(to_varchar((nullif(trim("BUILDING"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("HOUSE_NUMBER"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("PIN_CODE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STREET"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("HOUSE_NUMBER"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUILDING"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STREET"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("LOCATION"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("POST_OFFICE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PIN_CODE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("BUILDING"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("HOUSE_NUMBER"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("PIN_CODE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STREET"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("HOUSE_NUMBER"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUILDING"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STREET"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("LOCATION"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("POST_OFFICE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PIN_CODE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
),
k2 as (
    select parent_bk from g2_t0
    union
    select parent_bk from g2_t1
    union
    select parent_bk from g2_t2
    union
    select parent_bk from g2_t3
    union
    select parent_bk from g2_t4
    union
    select parent_bk from g2_t5
    union
    select parent_bk from g2_t6
    union
    select parent_bk from g2_t7
),
st2 as (  -- stitch_kyc_common_address recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           coalesce(g2_t0.addressline1, g2_t1.addressline1, g2_t3.addressline1, g2_t4.addressline1, g2_t5.addressline1) as addressline1,
           coalesce(g2_t3.addressline2, g2_t4.addressline2, g2_t5.addressline2) as addressline2,
           coalesce(g2_t3.addressline3, g2_t4.addressline3, g2_t5.addressline3) as addressline3,
           g2_t7.buildingname as buildingname,
           g2_t0.careofname as careofname,
           coalesce(g2_t3.city, g2_t4.city, g2_t5.city, g2_t6.city) as city,
           g2_t7.countrycode as countrycode,
           coalesce(g2_t3.countryname, g2_t4.countryname, g2_t5.countryname, g2_t6.countryname) as countryname,
           coalesce(g2_t6.doornumber, g2_t7.doornumber) as doornumber,
           coalesce(g2_t0.postalcode, g2_t3.postalcode, g2_t5.postalcode, g2_t6.postalcode, g2_t7.postalcode) as postalcode,
           coalesce(g2_t0.statename, g2_t2.statename, g2_t3.statename, g2_t4.statename, g2_t5.statename, g2_t6.statename, g2_t7.statename) as statename,
           coalesce(g2_t6.streetname, g2_t7.streetname) as streetname,
           array_to_string(array_construct_compact(
               case when g2_t0.parent_bk is not null then 'OPUS_BJAZ_M_KYC_DRIVING_LICENCE' end,
               case when g2_t1.parent_bk is not null then 'OPUS_BJAZ_M_KYC_GSTN' end,
               case when g2_t2.parent_bk is not null then 'OPUS_BJAZ_M_KYC_VOTER' end,
               case when g2_t3.parent_bk is not null then 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' end,
               case when g2_t4.parent_bk is not null then 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' end,
               case when g2_t5.parent_bk is not null then 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' end,
               case when g2_t6.parent_bk is not null then 'OPUS_BJAZ_T_EKYC' end,
               case when g2_t7.parent_bk is not null then 'OPUS_BJAZ_T_KYC_OCR' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g2_t0.inc_job_updated_at, g2_t1.inc_job_updated_at, g2_t2.inc_job_updated_at, g2_t3.inc_job_updated_at, g2_t4.inc_job_updated_at, g2_t5.inc_job_updated_at, g2_t6.inc_job_updated_at, g2_t7.inc_job_updated_at) as inc_job_updated_at
      from k2 ak
      left join g2_t0 on g2_t0.parent_bk = ak.parent_bk
      left join g2_t1 on g2_t1.parent_bk = ak.parent_bk
      left join g2_t2 on g2_t2.parent_bk = ak.parent_bk
      left join g2_t3 on g2_t3.parent_bk = ak.parent_bk
      left join g2_t4 on g2_t4.parent_bk = ak.parent_bk
      left join g2_t5 on g2_t5.parent_bk = ak.parent_bk
      left join g2_t6 on g2_t6.parent_bk = ak.parent_bk
      left join g2_t7 on g2_t7.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g2_t0.addressline1 nulls last, g2_t0.postalcode nulls last, g2_t0.statename nulls last, g2_t0.careofname nulls last, g2_t1.addressline1 nulls last, g2_t2.statename nulls last, g2_t3.addressline1 nulls last, g2_t3.addressline2 nulls last, g2_t3.addressline3 nulls last, g2_t3.city nulls last, g2_t3.countryname nulls last, g2_t3.postalcode nulls last, g2_t3.statename nulls last, g2_t4.addressline1 nulls last, g2_t4.addressline2 nulls last, g2_t4.addressline3 nulls last, g2_t4.city nulls last, g2_t4.countryname nulls last, g2_t4.statename nulls last, g2_t5.addressline1 nulls last, g2_t5.addressline2 nulls last, g2_t5.addressline3 nulls last, g2_t5.city nulls last, g2_t5.countryname nulls last, g2_t5.postalcode nulls last, g2_t5.statename nulls last, g2_t6.city nulls last, g2_t6.countryname nulls last, g2_t6.doornumber nulls last, g2_t6.postalcode nulls last, g2_t6.statename nulls last, g2_t6.streetname nulls last, g2_t7.buildingname nulls last, g2_t7.countrycode nulls last, g2_t7.doornumber nulls last, g2_t7.postalcode nulls last, g2_t7.statename nulls last, g2_t7.streetname nulls last) = 1
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_kyc_common_address
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.addressline1) as ADDRESSLINE1,
               to_varchar(st.addressline2) as ADDRESSLINE2,
               to_varchar(st.addressline3) as ADDRESSLINE3,
               to_varchar(st.buildingname) as BUILDINGNAME,
               to_varchar(st.city) as CITY,
               to_varchar(st.countrycode) as COUNTRYCODE,
               to_varchar(st.countryname) as COUNTRYNAME,
               to_varchar(st.doornumber) as DOORNUMBER,
               to_varchar(st.postalcode) as POSTALCODE,
               to_varchar(st.statename) as STATENAME,
               to_varchar(st.streetname) as STREETNAME,
               st.record_source as RECORD_SOURCE
          from st2 st
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r2 as (
    select 'ADDRESSLINE1' as column_name, c.hkey, c.ADDRESSLINE1 as sat_value,
           max(iff(equal_null(c.ADDRESSLINE1, e.ADDRESSLINE1), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ADDRESSLINE1) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.ADDRESSLINE1
    union all
    select 'ADDRESSLINE2' as column_name, c.hkey, c.ADDRESSLINE2 as sat_value,
           max(iff(equal_null(c.ADDRESSLINE2, e.ADDRESSLINE2), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ADDRESSLINE2) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.ADDRESSLINE2
    union all
    select 'ADDRESSLINE3' as column_name, c.hkey, c.ADDRESSLINE3 as sat_value,
           max(iff(equal_null(c.ADDRESSLINE3, e.ADDRESSLINE3), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ADDRESSLINE3) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.ADDRESSLINE3
    union all
    select 'BUILDINGNAME' as column_name, c.hkey, c.BUILDINGNAME as sat_value,
           max(iff(equal_null(c.BUILDINGNAME, e.BUILDINGNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.BUILDINGNAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.BUILDINGNAME
    union all
    select 'CITY' as column_name, c.hkey, c.CITY as sat_value,
           max(iff(equal_null(c.CITY, e.CITY), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.CITY) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.CITY
    union all
    select 'COUNTRYCODE' as column_name, c.hkey, c.COUNTRYCODE as sat_value,
           max(iff(equal_null(c.COUNTRYCODE, e.COUNTRYCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.COUNTRYCODE) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.COUNTRYCODE
    union all
    select 'COUNTRYNAME' as column_name, c.hkey, c.COUNTRYNAME as sat_value,
           max(iff(equal_null(c.COUNTRYNAME, e.COUNTRYNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.COUNTRYNAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.COUNTRYNAME
    union all
    select 'DOORNUMBER' as column_name, c.hkey, c.DOORNUMBER as sat_value,
           max(iff(equal_null(c.DOORNUMBER, e.DOORNUMBER), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DOORNUMBER) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.DOORNUMBER
    union all
    select 'POSTALCODE' as column_name, c.hkey, c.POSTALCODE as sat_value,
           max(iff(equal_null(c.POSTALCODE, e.POSTALCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.POSTALCODE) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.POSTALCODE
    union all
    select 'STATENAME' as column_name, c.hkey, c.STATENAME as sat_value,
           max(iff(equal_null(c.STATENAME, e.STATENAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STATENAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.STATENAME
    union all
    select 'STREETNAME' as column_name, c.hkey, c.STREETNAME as sat_value,
           max(iff(equal_null(c.STREETNAME, e.STREETNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STREETNAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.STREETNAME
    union all
    select 'RECORD_SOURCE' as column_name, c.hkey, c.RECORD_SOURCE as sat_value,
           max(iff(equal_null(c.RECORD_SOURCE, e.RECORD_SOURCE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.RECORD_SOURCE) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.RECORD_SOURCE
)
select 'OPUS' as project, 'SAT_COMMON_ADDRESS' as satellite, 'stitch_common_address (5 tables)' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
union all
select 'OPUS' as project, 'SAT_COMMON_ADDRESS' as satellite, 'stitch_kyc_common_address (6 tables)' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r2
 group by column_name
order by record_source, column_name;



----------------------------------------------------------------------------------------
-- 7. OPUS — [M1 | stitch_incremental] SAT_COMMON_ADMIN_GEOGRAPHY   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- automate_dv.sat; PK LOCATION_HKEY; 1 RECORD_SOURCE group(s):
-- stitch_shared__common_admin_geography_common_geo (2 tables) [1 col(s)]. Stitch groups:
-- expected values are the stitch view recomputed from RAW (same coalesce priority and
-- tie-break), and RECORD_SOURCE (contributing tables) is compared too.
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY
     where regexp_like(RECORD_SOURCE, '^(OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER)(, (OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER))*$')
     group by LOCATION_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select LOCATION_HKEY as hkey,
           to_varchar(PINCODE) as PINCODE,
           RECORD_SOURCE as RECORD_SOURCE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY
     where regexp_like(RECORD_SOURCE, '^(OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER)(, (OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER))*$')
       and LOCATION_HKEY in (select hkey from s1)
    qualify rank() over (partition by LOCATION_HKEY order by LOAD_DATETIME desc) = 1
),
g1_t0 as (  -- stitch source OPUS_BJAZ_PINCODE
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("PINCODE"::varchar), '')))), '') as pincode,
           nullif(trim(to_varchar((nullif(trim("ZONE1"::varchar), '')))), '') as regioncode,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as regionname,
           nullif(trim(to_varchar((nullif(trim("ZONE2"::varchar), '')))), '') as subzonecode,
           nullif(trim(to_varchar((nullif(trim("ZONE"::varchar), '')))), '') as zonecode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t1 as (  -- stitch source OPUS_BJAZ_PINCODE_MASTER
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("PINCODE"::varchar), '')))), '') as pincode,
           nullif(trim(to_varchar((nullif(trim("ZONE1"::varchar), '')))), '') as regioncode,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as regionname,
           nullif(trim(to_varchar((nullif(trim("ZONE2"::varchar), '')))), '') as subzonecode,
           nullif(trim(to_varchar((nullif(trim("ZONE_PIN"::varchar), '')))), '') as zonecode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t1
),
st1 as (  -- stitch_shared__common_admin_geography_common_geo recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           coalesce(g1_t0.pincode, g1_t1.pincode) as pincode,
           coalesce(g1_t0.regioncode, g1_t1.regioncode) as regioncode,
           coalesce(g1_t0.regionname, g1_t1.regionname) as regionname,
           coalesce(g1_t0.subzonecode, g1_t1.subzonecode) as subzonecode,
           coalesce(g1_t0.zonecode, g1_t1.zonecode) as zonecode,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_BJAZ_PINCODE' end,
               case when g1_t1.parent_bk is not null then 'OPUS_BJAZ_PINCODE_MASTER' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t1.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t1 on g1_t1.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.pincode nulls last, g1_t0.regioncode nulls last, g1_t0.regionname nulls last, g1_t0.subzonecode nulls last, g1_t0.zonecode nulls last, g1_t1.pincode nulls last, g1_t1.regioncode nulls last, g1_t1.regionname nulls last, g1_t1.subzonecode nulls last, g1_t1.zonecode nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_shared__common_admin_geography_common_geo
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.pincode) as PINCODE,
               st.record_source as RECORD_SOURCE
          from st1 st
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'PINCODE' as column_name, c.hkey, c.PINCODE as sat_value,
           max(iff(equal_null(c.PINCODE, e.PINCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PINCODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PINCODE
    union all
    select 'RECORD_SOURCE' as column_name, c.hkey, c.RECORD_SOURCE as sat_value,
           max(iff(equal_null(c.RECORD_SOURCE, e.RECORD_SOURCE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.RECORD_SOURCE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.RECORD_SOURCE
)
select 'OPUS' as project, 'SAT_COMMON_ADMIN_GEOGRAPHY' as satellite, 'stitch_shared__common_admin_geography_common_geo (2 tables)' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
order by record_source, column_name;



----------------------------------------------------------------------------------------
-- 8. OPUS — [M1 | stitch_incremental] SAT_PARTY_IDENTITY   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 9 RECORD_SOURCE group(s): stitch_party_identity (19
-- tables) [17 col(s)], OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [9 col(s)],
-- OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS [4 col(s)], OPUS_BJAZ_T_CKYC_SEARCH [3 col(s)],
-- OPUS_BJAZ_T_EKYC [3 col(s)], OPUS_BJAZ_T_KYC_AUTH [3 col(s)], OPUS_BJAZ_T_KYC_DETAILS
-- [3 col(s)], OPUS_BJAZ_T_KYC_INCOMING [4 col(s)], OPUS_BJAZ_T_KYC_OCR [5 col(s)].
-- Stitch groups: expected values are the stitch view recomputed from RAW (same coalesce
-- priority and tie-break), and RECORD_SOURCE (contributing tables) is compared too.
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES))*$')
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(AGE) as AGE,
           to_varchar(DATEOFBIRTH) as DATEOFBIRTH,
           to_varchar(DATEOFDEATH) as DATEOFDEATH,
           to_varchar(FIRSTNAME) as FIRSTNAME,
           to_varchar(GENDERCODE) as GENDERCODE,
           to_varchar(LASTNAME) as LASTNAME,
           to_varchar(MIDDLENAME) as MIDDLENAME,
           to_varchar(NAMESUFFIX) as NAMESUFFIX,
           to_varchar(NATIONALITY) as NATIONALITY,
           to_varchar(PARTYDISPLAYNAME) as PARTYDISPLAYNAME,
           to_varchar(PARTYFULLNAME) as PARTYFULLNAME,
           to_varchar(PARTYLEGALNAME) as PARTYLEGALNAME,
           to_varchar(PARTYSHORTNAME) as PARTYSHORTNAME,
           to_varchar(PARTYSTATUS) as PARTYSTATUS,
           to_varchar(PARTYTYPECODE) as PARTYTYPECODE,
           to_varchar(PLACEOFBIRTH) as PLACEOFBIRTH,
           to_varchar(SALUTATION) as SALUTATION,
           RECORD_SOURCE as RECORD_SOURCE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES))*$')
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
g1_t0 as (  -- stitch source OPUS_AZBJ_PARTNER_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("STATUS"::varchar), '')))), '') as partystatus,
