           g1_t20.dateofdeath as dateofdeath,
           coalesce(g1_t3.firstname, g1_t20.firstname) as firstname,
           coalesce(g1_t5.gendercode, g1_t6.gendercode, g1_t7.gendercode, g1_t8.gendercode, g1_t9.gendercode, g1_t10.gendercode, g1_t11.gendercode, g1_t13.gendercode, g1_t17.gendercode, g1_t18.gendercode, g1_t19.gendercode, g1_t20.gendercode) as gendercode,
           coalesce(g1_t3.lastname, g1_t7.lastname, g1_t20.lastname) as lastname,
